(()=>{
 const login=document.querySelector('#admin-login-form');if(!login)return;
 const status=document.querySelector('#admin-status'),panel=document.querySelector('#admin-panel'),section=document.querySelector('#admin-section'),item=document.querySelector('#admin-item'),fields=document.querySelector('#admin-fields');let content,sha,busy=false;
 const definitions={books:[['number','Numéro','number'],['title','Titre'],['slug','Adresse du livre (minuscules, tirets)'],['available','Livre paru','checkbox'],['release_month','Mois de parution prévu','month'],['price','Prix (€)','number'],['pages','Nombre de pages','number'],['isbn','ISBN'],['description','Présentation intégrale','textarea'],['cover','Couverture : adresse ou chemin'],['excerpts','Extraits : une adresse par ligne','lines'],['commande_url','Lien du produit SumUp'],['color','Couleur','color']],events:[['slug','Identifiant (minuscules, tirets)'],['title','Nom de la rencontre'],['start_date','Date de début','date'],['end_date','Date de fin (facultative)','date'],['city','Ville'],['place','Salle ou lieu'],['street','Adresse'],['postal_code','Code postal'],['confirmed','Informations confirmées','checkbox'],['description','Présentation','textarea'],['image','Photo : adresse ou chemin']],stores:[['slug','Identifiant (minuscules, tirets)'],['name','Nom du point de vente'],['address','Adresse'],['postal_code','Code postal'],['city','Ville'],['phone','Téléphone'],['url','Site internet']],subscription:[['min_books','Nombre minimal d’exemplaires','number'],['max_books','Nombre maximal d’exemplaires','number']]};
 async function call(body){const r=await fetch('/api/admin',{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{}),cache:'no-store',signal:AbortSignal.timeout(20000)});let answer;try{answer=await r.json();}catch{throw Error('Administration indisponible : utilisez votre déploiement Vercel configuré.');}if(!r.ok)throw Error(answer.error||'Opération impossible.');return answer;}
 function entries(){return content[section.value]||(content[section.value]=[]);}
 function current(){return section.value==='subscription'?(content.subscription||(content.subscription={min_books:3,max_books:12,max_parcel:3})):entries()[Number(item.value)];}
 function capture(){const row=current();if(!row)return;for(const [key,,type] of definitions[section.value]){const input=fields.querySelector(`[name="${key}"]`);if(!input)continue;row[key]=type==='checkbox'?input.checked:type==='number'?Number(input.value):type==='lines'?input.value.split('\n').map(s=>s.trim()).filter(Boolean):input.value;}if(section.value==='books'){row.status=row.available?'paru':row.release_month?'prochain':'plus_tard';}status.textContent='Modifications préparées. Cliquez sur Publier pour les enregistrer.';}
 function render(){fields.replaceChildren();const row=current();if(!row)return;for(const [key,label,type] of definitions[section.value]){const wrapper=document.createElement('label');wrapper.textContent=label;const input=document.createElement(type==='textarea'||type==='lines'?'textarea':'input');input.name=key;if(type!=='textarea'&&type!=='lines')input.type=type||'text';if(type==='number'){input.step=key==='price'?'0.01':'1';input.min='0';}if(type==='checkbox')input.checked=row[key]===true;else input.value=type==='lines'?(row[key]||[]).join('\n'):row[key]??'';if(type==='textarea'||type==='lines'){input.rows=6;wrapper.className='full';}wrapper.append(input);fields.append(wrapper);}
 if(section.value==='books'||section.value==='events'){const wrapper=document.createElement('label');wrapper.textContent=section.value==='books'?'Téléverser une couverture (JPEG, PNG, WebP, < 1 Mo)':'Téléverser une photo (< 1 Mo)';const file=document.createElement('input');file.type='file';file.accept='image/png,image/jpeg,image/webp';file.addEventListener('change',()=>{const image=file.files[0];if(!image)return;if(image.size>1000000||!['image/png','image/jpeg','image/webp'].includes(image.type)){status.textContent='Choisissez une image JPEG, PNG ou WebP de moins de 1 Mo.';return;}const reader=new FileReader();reader.onload=()=>{const field=fields.querySelector(`[name="${section.value==='books'?'cover':'image'}"]`);field.value=reader.result;capture();status.textContent='Image prête. Cliquez sur Publier pour l’enregistrer.';};reader.readAsDataURL(image);});wrapper.append(file);fields.append(wrapper);}}
 function choose(){document.querySelector('#admin-item-tools').hidden=section.value==='subscription';item.replaceChildren();if(section.value!=='subscription')entries().forEach((row,i)=>{const option=document.createElement('option');option.value=i;option.textContent=row.title||row.name||row.slug;item.append(option);});render();}
 async function load(){const answer=await call();content=answer.content;sha=answer.sha;panel.hidden=false;document.querySelector('#admin-login').hidden=true;choose();status.textContent='Contenus chargés depuis GitHub.';}
 login.addEventListener('submit',async e=>{e.preventDefault();try{await call({action:'login',password:document.querySelector('#admin-password').value});document.querySelector('#admin-password').value='';await load();}catch(error){status.textContent=error.message;}});
 fields.addEventListener('change',capture);section.addEventListener('change',choose);item.addEventListener('change',render);
 document.querySelector('#admin-add').addEventListener('click',()=>{const rows=entries(),slug='nouveau-'+Date.now();rows.push(section.value==='books'?{number:Math.max(0,...rows.map(x=>x.number))+1,title:'Nouveau livre',slug,available:false,price:15,pages:24,color:'#704575',description:'',cover:'',release_month:'',isbn:'',commande_url:''}:section.value==='events'?{slug,title:'Nouvelle rencontre',start_date:'',city:'',place:'',confirmed:false}:{slug,name:'Nouveau point de vente',address:'',city:'',phone:'',url:''});choose();item.value=rows.length-1;render();});
 document.querySelector('#admin-delete').addEventListener('click',()=>{if(!confirm('Retirer cet élément ? Le retrait ne sera effectif qu’après publication et pourra être annulé dans l’historique GitHub.'))return;entries().splice(Number(item.value),1);choose();});
 document.querySelector('#admin-editor').addEventListener('submit',async e=>{e.preventDefault();if(busy)return;capture();busy=true;const button=e.submitter;button.disabled=true;status.textContent='Enregistrement dans GitHub…';try{const answer=await call({action:'save',section:section.value,value:content[section.value],sha});sha=answer.sha;status.textContent=answer.message;}catch(error){status.textContent=error.message;}finally{busy=false;button.disabled=false;}});
 document.querySelector('#admin-reload').addEventListener('click',()=>load().catch(e=>status.textContent=e.message));
 document.querySelector('#admin-logout').addEventListener('click',async()=>{try{await call({action:'logout'});location.reload();}catch(error){status.textContent=error.message;}});
 load().catch(error=>{panel.hidden=true;status.textContent=error.message;});
})();
